<?php
declare(strict_types=1);
require __DIR__.'/app.php';
$page=(string)($_GET['page']??(auth()?'dashboard':'login'));
$count=(int)$db->query('SELECT COUNT(*) FROM usuarios')->fetch_row()[0];
if(!$count)$page='setup';
if(auth()){$uid=(int)$_SESSION['uid'];$s=$db->prepare('SELECT 1 FROM usuarios WHERE id=? AND activo=1');$s->bind_param('i',$uid);$s->execute();if(!$s->get_result()->num_rows){$_SESSION=[];session_regenerate_id(true);flash('error','Tu usuario fue desactivado.');go('index.php');}}

if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$action=(string)($_POST['action']??'');
 if($action==='setup'&&!$count){$u=trim((string)$_POST['usuario']);$p=(string)$_POST['clave'];if(strlen($u)>=3&&strlen($p)>=10){$h=password_hash($p,PASSWORD_DEFAULT);$r='admin';$s=$db->prepare('INSERT INTO usuarios(usuario,clave,rol) VALUES(?,?,?)');$s->bind_param('sss',$u,$h,$r);$s->execute();flash('ok','Administrador creado.');go('index.php');}flash('error','Usuario mínimo 3 y contraseña mínimo 10 caracteres.');go('index.php');}
 if($action==='login'){$u=trim((string)$_POST['usuario']);$s=$db->prepare('SELECT id,usuario,clave,rol FROM usuarios WHERE usuario=? AND activo=1');$s->bind_param('s',$u);$s->execute();$row=$s->get_result()->fetch_assoc();if($row&&password_verify((string)$_POST['clave'],$row['clave'])){session_regenerate_id(true);$_SESSION['uid']=(int)$row['id'];$_SESSION['user']=$row['usuario'];$_SESSION['rol']=$row['rol'];audit($db,'Inicio de sesión');go('index.php');}usleep(300000);flash('error','Datos incorrectos.');go('index.php');}
 if($action==='logout'&&auth()){audit($db,'Cierre de sesión');$_SESSION=[];session_destroy();go('index.php');}
 if(!auth())go('index.php');
 if($action==='product_save'){$f=product_fields();if(is_string($f)){flash('error',$f);go('index.php?page=productos');}$s=$db->prepare('INSERT INTO productos(producto,categoria,proveedor,cantidad,tiene_cambio,fecha_cambio,vencimiento) VALUES(?,?,?,?,?,?,?)');$s->bind_param('sssiiss',...$f);$s->execute();audit($db,'Producto registrado: '.$f[0]);flash('ok','Producto guardado.');go('index.php?page=productos');}
 // Los datos generales se aplican a todas las fechas del mismo producto; lote, cantidad, fecha de cambio y vencimiento solo a esta fila
 if($action==='product_update'){$id=(int)($_POST['id']??0);$f=product_fields();if(is_string($f)){flash('error',$f);go('index.php?page=productos');}$s=$db->prepare('SELECT COALESCE(producto_origen_id,id) FROM productos WHERE id=?');$s->bind_param('i',$id);$s->execute();$group=$s->get_result()->fetch_row()[0]??null;if($group===null){flash('error','El producto no existe.');go('index.php?page=productos');}$group=(int)$group;[$name,$cat,$provider,$qty,$exchange,$change,$date]=$f;$s=$db->prepare('UPDATE productos SET producto=?,categoria=?,proveedor=?,tiene_cambio=? WHERE COALESCE(producto_origen_id,id)=?');$s->bind_param('sssii',$name,$cat,$provider,$exchange,$group);$s->execute();$s=$db->prepare('UPDATE productos SET cantidad=?,fecha_cambio=?,vencimiento=? WHERE id=?');$s->bind_param('issi',$qty,$change,$date,$id);$s->execute();audit($db,'Producto editado: '.$name.' #'.$id);flash('ok','Producto actualizado.');go('index.php?page=productos');}
 if($action==='expiration_add'){$source=(int)($_POST['id']??0);$qty=max(0,(int)($_POST['cantidad']??0));$date=(string)($_POST['vencimiento']??'');if(!valid_date($date)){flash('error','Selecciona una fecha válida.');go('index.php?page=productos');}$s=$db->prepare('SELECT tiene_cambio FROM productos WHERE id=?');$s->bind_param('i',$source);$s->execute();$exchange=$s->get_result()->fetch_row()[0]??null;if($exchange===null){flash('error','El producto no existe.');go('index.php?page=productos');}$change=$exchange?(string)($_POST['fecha_cambio']??''):null;if($exchange&&($error=change_date_error($change,$date))){flash('error',$error);go('index.php?page=productos');}$s=$db->prepare('INSERT INTO productos(codigo,producto,categoria,proveedor,cantidad,tiene_cambio,fecha_cambio,producto_origen_id,vencimiento) SELECT codigo,producto,categoria,proveedor,?,tiene_cambio,?,COALESCE(producto_origen_id,id),? FROM productos WHERE id=?');$s->bind_param('issi',$qty,$change,$date,$source);$s->execute();audit($db,'Nuevo vencimiento agregado al producto #'.$source);flash('ok','Nueva fecha de vencimiento agregada.');go('index.php?page=productos');}
 if($action==='product_delete'&&admin()){$id=(int)$_POST['id'];$s=$db->prepare('DELETE FROM productos WHERE id=?');$s->bind_param('i',$id);$s->execute();audit($db,'Producto eliminado #'.$id);flash('ok','Producto eliminado.');go(($_POST['volver']??'')==='dashboard'?'index.php?page=dashboard':'index.php?page=productos');}
 if($action==='user_save'&&admin()){$u=trim((string)$_POST['usuario']);$p=(string)$_POST['clave'];$r=in_array($_POST['rol'],['admin','empleado'],true)?$_POST['rol']:'empleado';if(strlen($u)<3||strlen($p)<10){flash('error','Revisa usuario y contraseña.');go('index.php?page=usuarios');}$h=password_hash($p,PASSWORD_DEFAULT);try{$s=$db->prepare('INSERT INTO usuarios(usuario,clave,rol) VALUES(?,?,?)');$s->bind_param('sss',$u,$h,$r);$s->execute();audit($db,'Usuario creado: '.$u);flash('ok','Usuario creado.');}catch(Throwable $e){flash('error','El usuario ya existe.');}go('index.php?page=usuarios');}
 if($action==='user_toggle'&&admin()){$id=(int)($_POST['id']??0);if($id===(int)$_SESSION['uid']){flash('error','No puedes desactivar tu propio usuario.');go('index.php?page=usuarios');}$s=$db->prepare('UPDATE usuarios SET activo=1-activo WHERE id=?');$s->bind_param('i',$id);$s->execute();audit($db,'Estado cambiado del usuario #'.$id);flash('ok','Estado del usuario actualizado.');go('index.php?page=usuarios');}
 if($action==='user_password'&&admin()){$id=(int)($_POST['id']??0);$p=(string)($_POST['clave']??'');if(strlen($p)<10){flash('error','La contraseña debe tener mínimo 10 caracteres.');go('index.php?page=usuarios');}$h=password_hash($p,PASSWORD_DEFAULT);$s=$db->prepare('UPDATE usuarios SET clave=? WHERE id=?');$s->bind_param('si',$h,$id);$s->execute();audit($db,'Contraseña cambiada del usuario #'.$id);flash('ok','Contraseña actualizada.');go('index.php?page=usuarios');}
}
if(!auth()&&!in_array($page,['login','setup'],true))go('index.php');
if(auth()&&in_array($page,['login','setup'],true))go('index.php?page=dashboard');
if(in_array($page,['usuarios','historial'],true)&&!admin()){http_response_code(403);exit('Acceso denegado.');}
$flash=$_SESSION['flash']??null;unset($_SESSION['flash']);
function head(string $title):void{?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> | Control de vencimientos</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Sora:wght@500;600;700&family=Figtree:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap"><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="vence.css"><link rel="stylesheet" href="product_features.css"><link rel="stylesheet" href="alerts.css"><link rel="stylesheet" href="popup_fix.css"><script src="app.js" defer></script></head><body><?php }
if($page==='login'||$page==='setup'){head($page==='setup'?'Crear administrador':'Ingresar');?><main class="auth"><section class="login-card"><div class="logo">VENCE<span>+</span><small>CONTROL INTELIGENTE</small></div><h1><?=$page==='setup'?'Primer acceso':'Bienvenido'?></h1><p><?=$page==='setup'?'Crea la cuenta administradora.':'Ingresa para gestionar tu inventario.'?></p><?php if($flash):?><div class="alert <?=e($flash[0])?>"><?=e($flash[1])?></div><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="<?=$page==='setup'?'setup':'login'?>"><label>Usuario<input name="usuario" required autofocus></label><label>Contraseña<input type="password" name="clave" minlength="<?=$page==='setup'?'10':'1'?>" required></label><button><?=$page==='setup'?'Crear administrador':'Ingresar'?></button></form></section></main></body></html><?php exit;}
$alerts=(int)$db->query('SELECT COUNT(*) FROM productos WHERE vencimiento<=DATE_ADD(CURDATE(),INTERVAL '.DIAS_CRITICO.' DAY)')->fetch_row()[0];
$nav=['dashboard'=>['Resumen','<rect x="3" y="3" width="7" height="9" rx="1.5"/><rect x="14" y="3" width="7" height="5" rx="1.5"/><rect x="14" y="12" width="7" height="9" rx="1.5"/><rect x="3" y="16" width="7" height="5" rx="1.5"/>'],'productos'=>['Productos','<path d="M21 8 12 3 3 8v8l9 5 9-5z"/><path d="M3 8l9 5 9-5M12 13v8"/>']]+(admin()?['usuarios'=>['Usuarios','<circle cx="9" cy="8" r="4"/><path d="M2 21c0-4 3-7 7-7s7 3 7 7M17 4a4 4 0 0 1 0 8M22 21c0-3-1.5-5.5-4-6.5"/>'],'historial'=>['Historial','<path d="M3 12a9 9 0 1 0 3-6.7L3 8"/><path d="M3 3v5h5M12 7v5l3 2"/>']]:[]);
head(ucfirst($page));?><aside><div class="brand"><b>VENCE<span>+</span></b><small>Control inteligente</small></div><nav aria-label="Principal"><?php foreach($nav as $key=>[$text,$path]):?><a class="<?=$page===$key?'active':''?>" href="?page=<?=$key?>"<?=$page===$key?' aria-current="page"':''?>><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><?=$path?></svg><?=$text?><?php if($key==='productos'&&$alerts):?><span class="count" title="Vencidos o por vencer en <?=DIAS_CRITICO?> días"><?=$alerts?></span><?php endif?></a><?php endforeach?></nav><div class="rail-foot"><div class="user"><div class="avatar"><?=e(mb_strtoupper(mb_substr($_SESSION['user'],0,2)))?></div><div><b><?=e($_SESSION['user'])?></b><small><?=admin()?'Administrador':'Empleado'?></small></div></div><form method="post" class="logout"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="logout"><button>Cerrar sesión</button></form></div></aside><main class="content"><?php if($page!=='dashboard'):?><header><div><p class="eyebrow">Control de vencimientos</p><h1><?=e(ucfirst($page))?></h1></div></header><?php endif?><?php if($flash):?><div class="alert <?=e($flash[0])?>"><?=e($flash[1])?></div><?php endif?>
<?php if($page==='dashboard'):require __DIR__.'/dashboard_view.php';?>
<?php elseif($page==='productos'):require __DIR__.'/products_view.php';?>
<?php elseif($page==='usuarios'):$rows=$db->query('SELECT id,usuario,rol,activo,creado FROM usuarios ORDER BY id DESC');?><section class="panel"><h2>Nuevo usuario</h2><form method="post" class="grid-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="user_save"><label>Usuario<input name="usuario" required></label><label>Contraseña<input type="password" name="clave" minlength="10" required></label><label>Rol<select name="rol"><option value="empleado">Empleado</option><option value="admin">Administrador</option></select></label><button>Crear</button></form></section><section class="panel"><h2>Usuarios</h2><div class="table"><table><tr><th>Usuario</th><th>Rol</th><th>Estado</th><th>Creado</th><th>Acciones</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['usuario'])?></td><td><?=e($r['rol'])?></td><td><?=$r['activo']?'Activo':'Inactivo'?></td><td><?=e($r['creado'])?></td><td><details class="add-expiry"><summary>Contraseña</summary><form method="post" data-title="Cambiar contraseña de <?=e($r['usuario'])?>"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="user_password"><input type="hidden" name="id" value="<?=e($r['id'])?>"><label>Nueva contraseña<input type="password" name="clave" minlength="10" required></label><button>Guardar</button></form></details><?php if((int)$r['id']!==(int)$_SESSION['uid']):?><form method="post" class="inline-delete"<?=$r['activo']?' onsubmit="return confirm(\'¿Desactivar este usuario?\')"':''?>><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="user_toggle"><input type="hidden" name="id" value="<?=e($r['id'])?>"><button class="<?=$r['activo']?'delete':''?>"><?=$r['activo']?'Desactivar':'Activar'?></button></form><?php endif?></td></tr><?php endwhile?></table></div></section>
<?php elseif($page==='historial'):$rows=$db->query('SELECT usuario,accion,fecha FROM historial ORDER BY id DESC LIMIT 500');?><section class="panel"><h2>Actividad reciente</h2><div class="table"><table><tr><th>Usuario</th><th>Acción</th><th>Fecha</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['usuario'])?></td><td><?=e($r['accion'])?></td><td><?=e($r['fecha'])?></td></tr><?php endwhile?></table></div></section><?php endif?></main></body></html>
